#Get the current logged in user SID
$LoggedOnUser = (Get-CimInstance -ClassName Win32_ComputerSystem).Username

if ($LoggedOnUser) {
    # 3. Translate the username into their SID
    $currentsid = (New-Object System.Security.Principal.NTAccount($LoggedOnUser)).Translate([System.Security.Principal.SecurityIdentifier]).Value
    Write-Output "The logged-in user SID is: $currentsid"
} else {
    Write-Warning "No user is currently logged in."
}

#Define the path for the registry
