    $RegData = Get-ItemPropertyValue -Path $RegPath -Name $key

    #Convert the byte array to a hex string and compare
    if ($null -ne $RegData) {
        $CurrentHex = [System.BitConverter]::ToString($RegData)

        if ($CurrentHex -eq $ExpectedHex) {
            Write-Host "Key matches, nothing to do here"            
        } else {
            Write-Host "$key font is not the company defined font"
            $noncompliancecounter++            
        }
    } else {
       #Do nothing if the key doesn't exist
       Write-Host "No key found, device probally does not use Outlook, skipping.."
    }   
} 

 if ($noncompliancecounter++ -gt 0) {
        Write-Host "Found $noncompliancecounter settings not set to the default font, triggering change..."
        exit 1
    } else { 
        Write-Host "All fonts are properly set to their default setting, nothing to do here..."
        exit 0
} 
